import AppKit
import MacCleanKit

/// The icon in the dropdown's header. In this fork it is the Task Manager
/// app icon (assets/app_icon.svg at 256 px), embedded as base64 so it loads
/// the same under `swift run` and inside the app. The name is upstream's.
enum VacuumAsset {
    // NSImage isn't Sendable; this is built once and only read, so it's
    // safe to mark unchecked for Swift 6 strict concurrency.
    nonisolated(unsafe) static let image: NSImage = {
        let b64 = ""
        guard let data = Data(base64Encoded: b64), let img = NSImage(data: data) else {
            return NSImage(systemSymbolName: "wand.and.sparkles", accessibilityDescription: MCConstants.appName) ?? NSImage()
        }
        return img
    }()
}
